use std::cmp::Ordering;

fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // Since v is guaranteed non-empty and k is guaranteed to be in v,
    // we don’t have to worry about the search failing.
    let mut low = 0;
    let mut high = v.len() - 1;

    while low <= high {
        // Compute mid without overflow
        let mid = low + (high - low) / 2;
        match v[mid].cmp(&k) {
            Ordering::Equal => return mid,
            Ordering::Less => {
                // k must be to the right
                low = mid + 1;
            }
            Ordering::Greater => {
                // k must be to the left
                // Since k is in v, mid==0 && v[0]>k cannot actually happen,
                // but we guard against underflow to keep the code sound.
                if mid == 0 {
                    break;
                }
                high = mid - 1;
            }
        }
    }

    // Unreachable because of the precondition that k appears in v
    unreachable!("binary_search: target {} not found in {:?}", k, v);
}

